package dev.kuan.kuanperion.automation;
import java.util.*;
import static dev.kuan.kuanperion.automation.BookCombineTaskTest.*;
public final class BookReturnTransferTest {
 static final class Fixture {
  final Fake f=new Fake();final InventoryReceipts items=new InventoryReceipts();final CursorReceipts cursors=new CursorReceipts();boolean owned=true;ItemSnapshot carried=empty();
  final BookReturnTransfer transfer=new BookReturnTransfer(items,cursors,()->owned);final BookCombinePlanner.Book original;
  Fixture(){f.open(null);original=f.inventory.remove(9);f.placed.put(20,new BookCombinePlanner.Book(-1,original.item(),original.enchantments(),original.compatibility()));}
  BookReturnTransfer.Plan plan(){return BookReturnTransfer.select(f.view(),f.inventorySnapshot(),20,original,9,new InventoryProtection(Set.of("ENCHANTED_BOOK"),Set.of())).orElseThrow();}
  void begin(){check(transfer.begin(plan(),f.view(),f.inventorySnapshot(),carried,0),"explicit main-destination book plan");check(transfer.armNext(f.view(),f.inventorySnapshot(),carried,0),"arm exact external pickup");check(transfer.ticket().slot()==20&&transfer.ticket().click()==MenuContract.Click.PICKUP,"pickup not quick-move");check(transfer.armedStillMatches(f.view(),f.inventorySnapshot(),carried,0),"pickup revalidates at native boundary");check(transfer.sent(GuardedMenuAction.Result.SENT,0),"sent pickup");}
  void pickup(long t){f.placed.remove(20);carried=original.item();items.observe(1,4,20,f.menu().item(20));cursors.observe(1,4,carried,t);transfer.poll(f.view(),f.inventorySnapshot(),carried,false,t);}
  void deposit(){check(transfer.armNext(f.view(),f.inventorySnapshot(),carried,2*S),"arm exact empty main destination");check(transfer.ticket().slot()==54&&transfer.ticket().click()==MenuContract.Click.PICKUP,"empty explicit slot ticket, never hotbar/quick-move");check(transfer.armedStillMatches(f.view(),f.inventorySnapshot(),carried,2*S),"deposit retains prior pickup proof while arming new stamps");check(transfer.sent(GuardedMenuAction.Result.SENT,2*S),"sent deposit");}
  void gain(long t,boolean active,boolean canonical){f.inventory.put(9,original);carried=empty();if(active)items.observe(1,4,54,original.item());if(canonical)items.observe(1,0,9,original.item());cursors.observe(1,4,carried,t);transfer.poll(f.view(),f.inventorySnapshot(),carried,false,t);}
 }
 public static void main(String[]args){
  var x=new Fixture();x.begin();x.pickup(S);check(x.transfer.state()==BookReturnTransfer.State.READY&&x.transfer.step()==BookReturnTransfer.Step.DEPOSIT,"only actual source+own server cursor proof permits next step");x.deposit();x.gain(3*S,true,true);check(x.transfer.state()==BookReturnTransfer.State.CONFIRMED,"exact empty-main deposit, full43+both aliases+server empty cursor");check(x.transfer.confirmedStillMatches(x.f.view(),x.f.inventorySnapshot(),x.carried,3*S),"separate close revalidation");check(!x.transfer.armNext(x.f.view(),x.f.inventorySnapshot(),x.carried,4*S),"confirmed transfer never replays");
  x=new Fixture();x.begin();x.pickup(S);x.deposit();x.gain(3*S,false,true);check(x.transfer.state()==BookReturnTransfer.State.AWAITING,"canonical receipt cannot replace actual destination alias");x.items.observe(1,4,54,x.original.item());x.transfer.poll(x.f.view(),x.f.inventorySnapshot(),x.carried,false,4*S);check(x.transfer.state()==BookReturnTransfer.State.CONFIRMED,"missing own alias may settle boundedly");
  x=new Fixture();x.begin();x.pickup(S);x.deposit();x.gain(3*S,true,false);check(x.transfer.state()==BookReturnTransfer.State.AWAITING,"active alias cannot replace canonical destination receipt");x.items.observe(1,0,10,x.f.inventory.get(10).item());x.transfer.poll(x.f.view(),x.f.inventorySnapshot(),x.carried,false,4*S);check(x.transfer.state()==BookReturnTransfer.State.AWAITING,"unchanged sibling cannot bless predicted destination");
  x=new Fixture();x.begin();x.f.placed.remove(20);x.carried=x.original.item();x.items.observe(1,4,20,empty());x.transfer.poll(x.f.view(),x.f.inventorySnapshot(),x.carried,false,S);check(x.transfer.state()==BookReturnTransfer.State.AWAITING,"local carried book not authority to deposit");x.cursors.observe(1,4,x.carried,2*S);x.transfer.poll(x.f.view(),x.f.inventorySnapshot(),x.carried,false,2*S);check(x.transfer.state()==BookReturnTransfer.State.READY,"matching server carried receipt settles pickup");
  x=new Fixture();x.begin();x.f.placed.remove(20);x.items.observe(1,4,20,empty());x.gain(S,true,true);check(x.transfer.state()==BookReturnTransfer.State.CONFIRMED,"server may fulfill directly only into exact authorized destination with every proof");
  x=new Fixture();x.begin();x.f.placed.remove(20);x.carried=book(-1,4,"stranger",1).item();x.cursors.observe(1,4,x.carried,S);x.transfer.poll(x.f.view(),x.f.inventorySnapshot(),x.carried,false,S);check(x.transfer.state()==BookReturnTransfer.State.UNCERTAIN,"foreign carried item never repaired or deposited");
  x=new Fixture();x.begin();x.f.extra.put(40,AutoSellTaskTest.wheat(1));x.pickup(S);check(x.transfer.state()==BookReturnTransfer.State.UNCERTAIN,"protected/equipment drift cancels before destination action");
  x=new Fixture();x.begin();x.pickup(S);x.f.extra.put(0,AutoSellTaskTest.wheat(1));check(!x.transfer.armNext(x.f.view(),x.f.inventorySnapshot(),x.carried,2*S)&&x.transfer.state()==BookReturnTransfer.State.UNCERTAIN,"empty hotbar stays untouched; its later drift is still protected");
  x=new Fixture();x.begin();x.owned=false;x.pickup(S);check(x.transfer.state()==BookReturnTransfer.State.UNCERTAIN,"root revocation cannot advance");
  x=new Fixture();x.begin();x.transfer.poll(x.f.view(),x.f.inventorySnapshot(),x.carried,true,S);check(x.transfer.state()==BookReturnTransfer.State.UNCERTAIN,"manual input never repairs own cursor");
  x=new Fixture();x.begin();x.transfer.poll(x.f.view(),x.f.inventorySnapshot(),x.carried,false,8*S);check(x.transfer.state()==BookReturnTransfer.State.UNCERTAIN,"bounded phase timeout");
  x=new Fixture();x.begin();x.pickup(S);x.cursors.clear();check(!x.transfer.armNext(x.f.view(),x.f.inventorySnapshot(),x.carried,2*S),"clear epoch cannot authorize deposit");
  x=new Fixture();x.begin();x.f.placed.remove(20);x.carried=x.original.item();x.items.observe(1,4,20,empty());x.cursors.observe(1,5,x.carried,S);x.transfer.poll(x.f.view(),x.f.inventorySnapshot(),x.carried,false,S);check(x.transfer.state()==BookReturnTransfer.State.AWAITING,"wrong container cursor is no proof");
  x=new Fixture();var p=x.plan();check(BookReturnTransfer.select(x.f.view(),x.f.inventorySnapshot(),20,x.original,0,new InventoryProtection(Set.of("ENCHANTED_BOOK"),Set.of())).isEmpty(),"no hotbar destination");check(BookReturnTransfer.select(x.f.view(),x.f.inventorySnapshot(),20,x.original,10,new InventoryProtection(Set.of("ENCHANTED_BOOK"),Set.of())).isEmpty(),"no occupied destination/merge");check(BookReturnTransfer.select(x.f.view(),x.f.inventorySnapshot(),20,x.original,9,new InventoryProtection(Set.of("ENCHANTED_BOOK"),Set.of("one"))).isEmpty(),"protected original never picked");
  check(x.transfer.begin(p,x.f.view(),x.f.inventorySnapshot(),empty(),0)&&x.transfer.armNext(x.f.view(),x.f.inventorySnapshot(),empty(),0),"uncertain send fixture");check(!x.transfer.sent(GuardedMenuAction.Result.UNCERTAIN,0)&&x.transfer.state()==BookReturnTransfer.State.UNCERTAIN&&!x.transfer.armNext(x.f.view(),x.f.inventorySnapshot(),empty(),S),"possibly-sent failure never replays");
  System.out.println("BookReturnTransferTest: PASS (explicit empty main slot, own server-carried book, both applied aliases/full43/cursor, controlled pickup/deposit/direct fulfillment, no merge/hotbar/repair/retry)");
 }
}
